function AddSpin($n){if($n -lt 0 -or $n -gt 36){$message.Text='Enter 0 through 36.';return};[void]$history.Add($n);foreach($g in 0..5){if($betSteps[$g] -gt 0){$hit=$false;if($n -ne 0){$d=if($n -le 12){0}elseif($n -le 24){1}else{2};$c=3+(($n-1)%3);$hit=($g -eq $d -or $g -eq $c)};if($hit){$betSteps[$g]=0}else{$betSteps[$g]++;if($betSteps[$g] -gt ($lossLimit.SelectedIndex+1)){$betSteps[$g]=0;$message.Text='Loss limit reached - sequence stopped.'}}}};$message.Text='';Refresh}
