$entry=New-Object Windows.Forms.TextBox;$entry.Location=New-Object Drawing.Point(10,195);$entry.Width=220;$entry.BackColor=$dark;$entry.ForeColor=$cream;$go=New-Object Windows.Forms.Button;$go.Text='Record';$go.Location=New-Object Drawing.Point(240,193);$go.Size=New-Object Drawing.Size(90,29);$go.BackColor=$gold;$go.ForeColor=$dark;$go.Add_Click({$n=0;if([int]::TryParse($entry.Text,[ref]$n)){AddSpin $n;$entry.Text=''}else{$message.Text='Enter 0 through 36.'}});$undo=New-Object Windows.Forms.Button;$undo.Text='Undo';$undo.Location=New-Object Drawing.Point(340,193);$undo.Size=New-Object Drawing.Size(75,29);$undo.Add_Click({if($history.Count){$history.RemoveAt($history.Count-1);Refresh}});$message=L '' 10 235 $red;$gridPanel.Controls.AddRange([Windows.Forms.Control[]]@($entry,$go,$undo,$message));$main.Controls.Add($gridPanel)
