$cards=New-Object Windows.Forms.TableLayoutPanel;$cards.Size=New-Object Drawing.Size(720,210);$cards.ColumnCount=3;$cards.RowCount=2;for($i=0;$i -lt 3;$i++){$cards.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle([Windows.Forms.SizeType]::Percent,33.3)))};for($i=0;$i -lt 2;$i++){$cards.RowStyles.Add((New-Object Windows.Forms.RowStyle([Windows.Forms.SizeType]::Percent,50)))};$names=@('1st Dozen 1-12','2nd Dozen 13-24','3rd Dozen 25-36','Column 1','Column 2','Column 3');for($i=0;$i -lt 6;$i++){$card=P 95;$card.Dock='Fill';$name=L $names[$i] 10 10 $gold;$value=L '0 hits   0 absent' 10 42 $cream;$value.Font=New-Object Drawing.Font('Consolas',13,[Drawing.FontStyle]::Bold);$trigger=New-Object Windows.Forms.ComboBox;$trigger.DropDownStyle='DropDownList';[void]$trigger.Items.AddRange([object[]](3,4,5,6,7,8,10));$trigger.SelectedItem=5;$trigger.Location=New-Object Drawing.Point(215,8);$trigger.Width=105;$trigger.Tag=$i;$trigger.Add_SelectedIndexChanged({$triggers[[int]$this.Tag]=[int]$this.SelectedItem;Refresh});$action=New-Object Windows.Forms.Button;$action.Location=New-Object Drawing.Point(10,66);$action.Size=New-Object Drawing.Size(145,24);$action.BackColor=$gold;$action.ForeColor=$dark;$action.Tag=$i;$action.Add_Click({$g=[int]$this.Tag;if($betSteps[$g] -gt 0){$betSteps[$g]=0}else{$betSteps[$g]=1};Refresh});$card.Controls.AddRange([Windows.Forms.Control[]]@($name,$value,$action));$cardValues+=$value;$triggerBoxes+=$trigger;$betButtons+=$action;$cards.Controls.Add($card,$i%3,[math]::Floor($i/3))};$main.Controls.Add($cards)
